ALTER TABLE "kaizen_projects" ADD COLUMN "createdById" UUID, ADD COLUMN "reviewedById" UUID, ADD COLUMN "submittedAt" TIMESTAMP(3), ADD COLUMN "reviewedAt" TIMESTAMP(3);
CREATE TABLE "kaizen_audit_events" ("id" UUID NOT NULL PRIMARY KEY, "tenantId" UUID NOT NULL, "projectId" UUID NOT NULL, "actorId" UUID NOT NULL, "action" TEXT NOT NULL, "fromStatus" "KaizenStatus", "toStatus" "KaizenStatus" NOT NULL, "comment" VARCHAR(2000), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "kaizen_audit_events_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id"), CONSTRAINT "kaizen_audit_events_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "kaizen_projects"("id") ON DELETE CASCADE);
CREATE INDEX "kaizen_audit_events_tenantId_projectId_createdAt_idx" ON "kaizen_audit_events"("tenantId","projectId","createdAt");
